package ultra.downloads;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class DL28PolishTest {
 Activity c;
 @Before public void setup()throws Exception{c=Robolectric.buildActivity(Activity.class).setup().get();c.setTheme(android.R.style.Theme_Material_NoActionBar);app.revanced.extension.shared.utils.Utils.testContext=c;Art.network=false;Art.memory.evictAll();Library.wiping=false;java.lang.reflect.Field field=Library.class.getDeclaredField("items");field.setAccessible(true);field.set(null,null);new File(c.getFilesDir(),"ultra_downloads_v1.json").delete();Library.prefs(c).edit().clear().commit();}
 Library.Item file(String id,String name)throws Exception{Library.Item i=Library.add(c,id,name);File f=new File(c.getCacheDir(),name+".mp3");try(FileOutputStream o=new FileOutputStream(f)){o.write(new byte[]{1,2,3});}i.uri=f.getPath();i.state="done";Library.save(c);return i;}
 void waitFor(PermanentDelete d)throws Exception{for(int n=0;n<100&&d.busy;n++){Thread.sleep(20);Shadows.shadowOf(Looper.getMainLooper()).idle();}Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(d.busy);}
 @Test public void surfacesArePitchBlack(){assertEquals(Color.BLACK,NativeUi.background(c));assertEquals(Color.BLACK,NativeUi.sheet(c));assertEquals(Color.BLACK,NativeUi.placeholder(c));}
 @Test public void missingArtHasImmediateIconAndNoNetwork(){Library.Item i=new Library.Item();i.id="zzzzzzzzzzz";ImageView image=new ImageView(c);int jobs=Art.started.get();Art.load(c,i,image);assertNotNull(image.getDrawable());assertEquals(jobs,Art.started.get());assertEquals(i.id,image.getTag());}
 @Test public void mediaDeletionOnlyAcceptsExactAudioItems(){assertTrue(PermanentDelete.media("content://media/external/audio/media/23"));assertTrue(PermanentDelete.media("content://media/external_primary/audio/media/24"));for(String uri:new String[]{"content://media/external/audio/media","content://media/external/audio/media/23/children","content://media/external/images/media/23","content://other/external/audio/media/23","https://example.com/a.mp3","/sdcard/Music/"})assertFalse(uri,PermanentDelete.media(uri));}
 @Test public void constructionAndCancelNeverDelete()throws Exception{Library.Item i=file("abcdefghijk","CancelSong");PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});assertTrue(new File(i.uri).isFile());d.waiting=true;d.result(Activity.RESULT_CANCELED);assertTrue(new File(i.uri).isFile());assertNotNull(Library.get(c,i.id));}
 @Test public void selectedFileDeletedButOtherFilesAndOnlinePrefsUnchanged()throws Exception{Library.Item selected=file("abcdefghijk","Selected"),other=file("lmnopqrstuv","Keep");Library.prefs(c).edit().putString("local_playlist_index","online-source-unchanged").commit();String uri=selected.uri;PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(selected),()->{});d.start();waitFor(d);assertEquals(1,d.deleted);assertFalse(new File(uri).exists());assertTrue(new File(other.uri).isFile());assertNull(Library.get(c,selected.id));assertNotNull(Library.get(c,other.id));assertEquals("online-source-unchanged",Library.prefs(c).getString("local_playlist_index",""));}
 @Test public void changedUriAfterConfirmationIsRejected()throws Exception{Library.Item i=file("abcdefghijk","Old");String original=i.uri;PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});i.uri=file("lmnopqrstuv","New").uri;d.start();assertFalse(d.busy);assertTrue(new File(original).isFile());assertTrue(new File(i.uri).isFile());assertNotNull(Library.get(c,i.id));}
 @Test public void importedRawPathsAreNeverDeleted()throws Exception{Library.Item i=file("abcdefghijk","Imported");i.imported=true;PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});d.start();waitFor(d);assertEquals(0,d.deleted);assertEquals(1,d.failed);assertTrue(new File(i.uri).isFile());assertNotNull(Library.get(c,i.id));}
 @Test public void duplicateSelectionDeletesOnce()throws Exception{Library.Item i=file("abcdefghijk","Once");PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i,i),()->{});assertEquals(1,d.targets.size());d.start();waitFor(d);assertEquals(1,d.deleted);}
 @Test public void pendingAndroidConsentSurvivesRecreationWithoutRetargeting()throws Exception{Library.Item i=file("abcdefghijk","Rotate");PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});d.waiting=d.busy=true;d.systemDeleted=true;Bundle saved=d.save();PermanentDelete restored=PermanentDelete.restore(c,c,saved,()->{});assertNotNull(restored);assertTrue(restored.waiting);assertTrue(restored.systemDeleted);assertEquals(i.uri,restored.targets.get(0).uri);restored.result(Activity.RESULT_CANCELED);assertTrue(new File(i.uri).exists());assertFalse(restored.busy);}
 @Test public void dialogsHaveRoundedBlackWindow(){AlertDialog d=NativeUi.dialog(c).setTitle("Delete selected songs?").setMessage("Only selected device files").setPositiveButton("Delete permanently",null).setNegativeButton("Cancel",null).show();assertTrue(d.getWindow().getDecorView().getClipToOutline());assertTrue(d.getWindow().getDecorView().getBackground()!=null);assertEquals(Color.WHITE,d.getButton(-1).getCurrentTextColor());d.dismiss();}
 @Test public void downloadsScreenshotAndConfirmSnapshot()throws Exception{file("abcdefghijk","Kesariya");file("lmnopqrstuv","Raatan Lambiyan");android.widget.FrameLayout mount=new android.widget.FrameLayout(c);c.setContentView(mount);DownloadsScreen screen=new DownloadsScreen(c,mount,new Intent());java.lang.reflect.Field fg=DownloadsScreen.class.getDeclaredField("foreground");fg.setAccessible(true);fg.setBoolean(screen,false);java.lang.reflect.Method render=DownloadsScreen.class.getDeclaredMethod("render",boolean.class);render.setAccessible(true);render.invoke(screen,true);snapshot(mount,"DL28-downloads");java.lang.reflect.Method menu=DownloadsScreen.class.getDeclaredMethod("deleteConfirm",Library.Item.class);menu.setAccessible(true);menu.invoke(screen,Library.get(c,"abcdefghijk"));AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();snapshot(d.getWindow().getDecorView(),"DL28-delete-confirmation");d.dismiss();screen.destroy();}
 void clearIndicators(View v){v.setScrollIndicators(0);if(v instanceof android.view.ViewGroup)for(int n=0;n<((android.view.ViewGroup)v).getChildCount();n++)clearIndicators(((android.view.ViewGroup)v).getChildAt(n));}
 void snapshot(View view,String name)throws Exception{clearIndicators(view);boolean dialog=name.contains("confirmation");view.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,dialog?View.MeasureSpec.AT_MOST:View.MeasureSpec.EXACTLY));view.layout(0,0,400,view.getMeasuredHeight());Bitmap b=Bitmap.createBitmap(400,800,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(b);cv.drawColor(Color.BLACK);if(dialog)cv.translate(0,(800-view.getMeasuredHeight())/2f);view.draw(cv);new File("qa").mkdirs();try(FileOutputStream out=new FileOutputStream("qa/"+name+".png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}}
}
